    {"id":"sample_hh_944092612642014824","name":"史賓瑟．金．路易斯","memberIds":["944092612642014825","944092612642014826","944092612642014827","944092612642014828","944092612642014829"],"bio":"好吧，以下是詳細分解：丹尼斯．金和莉迪亞．史賓瑟生了一個女兒叫做艾莉絲．史賓瑟．金，然後離婚了。艾莉絲嫁給艾瑞克．路易斯，然後有了她自己的女兒奧莉維亞．金．路易斯。他們和艾莉絲的父親（還記得丹尼斯吧？）和艾瑞克的母親薇薇安．路易斯一起住。喂，可從沒人說過家庭這回事很簡單！","coverImage":null,"freeLayout":false,"manualPositions":{},"locked":false,"gameImport":true,"gameData":{"householdId":"944092612642014824","homeZoneId":"944092612642014166","worldId":"2474553381","neighborhoodId":"944092612642013589","regionId":"8086","lotName":"扁柏街道","worldName":"","neighborhoodName":"柳溪","hidden":false,"isActiveHousehold":true,"isPlayedHousehold":true,"isPlayerHousehold":true,"householdMemberIds":["944092612642014825","944092612642014826","944092612642014827","944092612642014828","944092612642014829"],"petIds":[]}},
    {"id":"sample_hh_944092612642085335","name":"朗德古拉伯","memberIds":["944092612642085336","944092612642085337","944092612642085338"],"bio":"朗德古拉伯一家似乎家庭美滿、有錢、有禮且勇敢。但萳西和傑佛瑞似乎隱藏著什麼。他們的秘密會讓他們走向陌路，還是會讓他們繼續建立起屬於自己的富裕王朝？","coverImage":null,"freeLayout":false,"manualPositions":{},"locked":false,"gameImport":true,"gameData":{"householdId":"944092612642085335","homeZoneId":"944092612642084491","worldId":"1185542770","neighborhoodId":"944092612642084078","regionId":"15740","lotName":"阿福伊斯塔豪宅","worldName":"","neighborhoodName":"綠洲之泉","hidden":false,"isActiveHousehold":false,"isPlayedHousehold":false,"isPlayerHousehold":false,"householdMemberIds":["944092612642085336","944092612642085337","944092612642085338"],"petIds":[]}},
    {"id":"sample_hh_944092612642081635","name":"高斯","memberIds":["944092612642081636","944092612642081637","944092612642081638","944092612642081639"],"bio":"高斯是懷著貴族氣息，被陰鬱圍繞的家族。夾在摩提梅爾所寫的恐怖故事與貝拉的神祕消失之間，卡珊多拉與亞歷山大會不會也同樣長大成為陰沉的人？","coverImage":null,"freeLayout":false,"manualPositions":{},"locked":false,"gameImport":true,"gameData":{"householdId":"944092612642081635","homeZoneId":"944092612642081327","worldId":"2280805822","neighborhoodId":"944092612642013589","regionId":"8086","lotName":"歐菲莉亞維拉","worldName":"","neighborhoodName":"柳溪","hidden":false,"isActiveHousehold":false,"isPlayedHousehold":false,"isPlayerHousehold":false,"householdMemberIds":["944092612642081636","944092612642081637","944092612642081638","944092612642081639"],"petIds":[]}},
    {"id":"sample_hh_944092612642563313","name":"伊藤","memberIds":["944092612642563314","944092612642563315","944092612642563316","944092612642563317"],"bio":"伊藤惠從小在千葉町長大。身為金牌滑雪運動員，她希望讓自己的兒女也有相同的成長環境，但過往戀情的記憶卻可能令她分神。伊藤直樹也是拿過獎牌的運動員。身為充滿算計的商人，他打造木漏隙光山的願景極具爭議，包括更多觀光人潮、更多錢，以及更多現代化舉措。七海和清皆有著父母的運動天賦，但他們的心卻另繫他方……七海只想當個孩子，而清則迷戀起坡道外的其他事物……","coverImage":null,"freeLayout":false,"manualPositions":{},"locked":false,"gameImport":true,"gameData":{"householdId":"944092612642563313","homeZoneId":"944092612642562894","worldId":"1491052508","neighborhoodId":"944092612642496440","regionId":"246370","lotName":"2-5-1 若葉森","worldName":"","neighborhoodName":"木漏隙光山","hidden":false,"isActiveHousehold":false,"isPlayedHousehold":false,"isPlayerHousehold":false,"householdMemberIds":["944092612642563314","944092612642563315","944092612642563316","944092612642563317"],"petIds":[]}},
    {"id":"sample_hh_944092612642294748","name":"維托","memberIds":["944092612642294749","944092612642294750"],"bio":"維托家的兄弟姐妹幾年前搬進遺忘山谷並努力讓遺忘山谷成為他們的家。這有時並不容易，因位他們和弗拉德勞斯．斯特勞處得不是很好，但被問到這點時，他們只提到他們對烹飪的品味不太相同。","coverImage":null,"freeLayout":false,"manualPositions":{},"locked":false,"gameImport":true,"gameData":{"householdId":"944092612642294748","homeZoneId":"944092612642294464","worldId":"3950992577","neighborhoodId":"944092612642294034","regionId":"146196","lotName":"附子草莊園","worldName":"","neighborhoodName":"遺忘山谷","hidden":false,"isActiveHousehold":false,"isPlayedHousehold":false,"isPlayerHousehold":false,"householdMemberIds":["944092612642294749","944092612642294750"],"petIds":[]}},
    {"id":"sample_hh_944092612642774242","name":"達榮","memberIds":["944092612642774243","944092612642774244","944092612642774245","944092612642774246"],"bio":"「團結帶來力量」是達榮家族的家訓。他們也確實世世代代同心一體……但這真能永遠持續嗎？年邁的世家首領阿德科亞，自女兒賈瓦拉年幼時，便夢想她有朝一日成為女王。多年來，她也證明自己是絕佳人選，透過慈善事業在全王國贏得青睞。她登上王冠的道路似乎正一路順遂，直到丈夫猝不及防的早逝。彷彿這還不夠，隨著她的人氣日漸高漲，越來越多好事之徒開始打探達榮家，追究這個看似完美的家族是否真的毫無醜聞可言。挑戰接踵而來之際，賈瓦拉仍奮勇向前，集結摯愛家族的力量，支撐她在爭奪王冠的競逐中挺進。","coverImage":null,"freeLayout":false,"manualPositions":{},"locked":false,"gameImport":true,"gameData":{"householdId":"944092612642774242","homeZoneId":"944092612642773392","worldId":"312126436","neighborhoodId":"944092612642770511","regionId":"487001","lotName":"丹貝萊宮殿","worldName":"","neighborhoodName":"昂達里昂","hidden":false,"isActiveHousehold":false,"isPlayedHousehold":false,"isPlayerHousehold":false,"householdMemberIds":["944092612642774243","944092612642774244","944092612642774245","944092612642774246"],"petIds":[]}},
    {"id":"sample_hh_944092612642152259","name":"室友","memberIds":["944092612642152260","944092612642152261","944092612642152262","944092612642152263"],"bio":"這個家庭看來就像是從電視情境喜劇裡搬出來的。這個星期得意的柔依、隨和的米契、淑女情人 J、還有知性的蓋文又會有什麼古怪的倒楣事呢？記得收看哦！","coverImage":null,"freeLayout":false,"manualPositions":{},"locked":false,"gameImport":true,"gameData":{"householdId":"944092612642152259","source":"game","homeZoneId":"944092612642151797","worldId":"711065386","neighborhoodId":"944092612642084078","regionId":"15740","lotName":"仙人掌之家","worldName":null,"neighborhoodName":"綠洲之泉","hidden":false,"isActiveHousehold":false,"isPlayedHousehold":false,"isPlayerHousehold":false,"householdMemberIds":["944092612642152260","944092612642152261","944092612642152262","944092612642152263"],"petIds":[]}},
    {"id":"sample_hh_944092612642082959","name":"永遠的麻吉","memberIds":["944092612642082960","944092612642082961","944092612642082962"],"bio":"自由自在的李柏緹、活潑的桑默與宅宅崔維斯是不太相像的好友，沒什麼可以拆散他們三個。除了桑默與李柏緹對崔維斯那慢慢增長、若有似無的情意…","coverImage":null,"freeLayout":false,"manualPositions":{},"locked":false,"gameImport":true,"gameData":{"householdId":"944092612642082959","source":"game","homeZoneId":"944092612642082541","worldId":"1902162923","neighborhoodId":"944092612642013589","regionId":"8086","lotName":"園藝精華","worldName":null,"neighborhoodName":"柳溪","hidden":false,"isActiveHousehold":false,"isPlayedHousehold":false,"isPlayerHousehold":false,"householdMemberIds":["944092612642082960","944092612642082961","944092612642082962"],"petIds":[]}},
    {"id":"sample_hh_944092612642567011","name":"普萊斯","memberIds":["944092612642567012","944092612642567013","944092612642567014","944092612642567015","944092612642567016","944092612642567017"],"bio":"高中甜心情侶暨考柏戴爾校友賈妮和馬瑟爾‧普萊斯回來了，並且帶著三名小孩一起搬回了故鄉的社區，他們分別叫作席妮、薩凡娜和傑登。他們還歡迎國外的交換學生凱文住進他們充滿活力的家中。這是個忙碌的家庭，隨時充滿活動和積極向上的追求。在馬瑟爾忙著寫出最新一集的小說時，賈妮則有著區域經理的成功正職工作。雙胞胎席妮和薩凡娜都相當喜歡自己的興趣，同時也努力維持著好成績。傑登很常向自己的姐姐們看齊，並且也等不及想變得跟她們一樣了，而他的好兄弟凱文也是一樣。有時候生活會讓他們有些疏離或摩擦，但他們知道他們隨時都能互相依賴。","coverImage":null,"freeLayout":false,"manualPositions":{},"locked":false,"gameImport":true,"gameData":{"householdId":"944092612642567011","source":"game","homeZoneId":"944092612642566651","worldId":"1505295608","neighborhoodId":"944092612642565247","regionId":"290968","lotName":"橋溪大道","worldName":null,"neighborhoodName":"考柏戴爾","hidden":false,"isActiveHousehold":false,"isPlayedHousehold":false,"isPlayerHousehold":false,"householdMemberIds":["944092612642567012","944092612642567013","944092612642567014","944092612642567015","944092612642567016","944092612642567017"],"petIds":[]}},
    {"id":"sample_hh_944092612642295964","name":"林克斯","memberIds":["944092612642295965"],"bio":"社區裡的貓很清楚要上哪去吃頓大餐。卡特琳娜對動物總是很心軟，和她住在一起的貓擁有貓咪們所能奢求的最好的家。有時候卡特琳娜會自問，生命的意義是否不僅止於貓...通常她想完就隨即又收留了另一隻浪貓。","coverImage":null,"freeLayout":false,"manualPositions":{},"locked":false,"gameImport":true,"gameData":{"householdId":"944092612642295964","source":"game","homeZoneId":"944092612642295773","worldId":"2893613071","neighborhoodId":"944092612642295103","regionId":"160112","lotName":"貓抓小屋","worldName":null,"neighborhoodName":"虎斑灣","hidden":false,"isActiveHousehold":false,"isPlayedHousehold":false,"isPlayerHousehold":false,"householdMemberIds":["944092612642295965","944092612642295966","944092612642295967","944092612642295968","944092612642295969"],"petIds":["944092612642295966","944092612642295967","944092612642295968","944092612642295969"]}},
    {"id":"sample_hh_944092612642297039","name":"戴爾加托","memberIds":["944092612642297040","944092612642297041","944092612642297042","944092612642297043"],"bio":"雖然塞普莉亞很愛她全職媽媽的工作，但要壓抑她當個受過充分訓練的獸醫的夢想卻越來越難。尤其是現在虎斑獸醫診所的老闆想把診所賣掉。她的先生賈斯汀一直都很支持，且一直提議要暫時離開工作崗位，好讓她追求自己的夢想。但塞普莉亞真的可以信任他能在布魯和巴塞羅謬之間維持家裡的和平嗎？更別說還有皮爾斯和伊薇了！","coverImage":null,"freeLayout":false,"manualPositions":{},"locked":false,"gameImport":true,"gameData":{"householdId":"944092612642297039","source":"game","homeZoneId":"944092612642296585","worldId":"1906928472","neighborhoodId":"944092612642295103","regionId":"160112","lotName":"弗萊斯莊園","worldName":null,"neighborhoodName":"虎斑灣","hidden":false,"isActiveHousehold":false,"isPlayedHousehold":false,"isPlayerHousehold":false,"householdMemberIds":["944092612642297040","944092612642297041","944092612642297042","944092612642297043","944092612642297044","944092612642297045"],"petIds":["944092612642297044","944092612642297045"]}},
    {"id":"sample_hh_944092612642773237","name":"蓋普","memberIds":["944092612642773238","944092612642773239","944092612642773240","944092612642773241"],"bio":"提伯特的人生可說是樣樣不缺——擁有所有人夢寐以求的模擬幣，還有一棟適合舉辦豪華派對的夢想豪宅。哦，還有，自從把妹妹茱麗葉趕走之後，他就是貝拉科德中地位最高的貴族。但也許他還能得到更多？畢竟，在昂達里昂還有誰比他這樣的富翁更適合當國王？他完美形象中唯一的小污點，就是三個孩子都已長大，卻堅持長期單身、拒絕安定下來！首先是碧翠絲，她是整個王國都愛戴的明珠，她明明可以選任何人，卻還在抱怨自己渴望更「有意義」的東西。接著是理想主義者瑟勒絲特，她居然相信家族那一套關於榮譽與騎士精神的家訓就該被當真。真是天真到極點。最後是維吉里歐。呃。真是丟臉的兒子，老是批評上流社會，說他們虛偽。為什麼他就不能像提伯特一樣，好好享受他的財富呢！","coverImage":null,"freeLayout":false,"manualPositions":{},"locked":false,"gameImport":true,"gameData":{"householdId":"944092612642773237","source":"game","homeZoneId":"944092612642772392","worldId":"2697210009","neighborhoodId":"944092612642770511","regionId":"487001","lotName":"貝拉科德宮殿","worldName":null,"neighborhoodName":"昂達里昂","hidden":false,"isActiveHousehold":false,"isPlayedHousehold":false,"isPlayerHousehold":false,"householdMemberIds":["944092612642773238","944092612642773239","944092612642773240","944092612642773241"],"petIds":[]}},
    {"id":"sample_hh_944092612642842853","name":"阿布蘭特斯","memberIds":["944092612642842854","944092612642842855"],"bio":"在長子與底比家族的女性繼承人成功聯姻後，艾梅琳達．阿布蘭特斯理應能安心退休才對。但她希望家族更上一層樓的野心並未隨著歲月一同流逝。在家族政治與權力鬥爭之間，她正值青春年少的女兒蘇菲亞往往只是貴族生活的天真旁觀者，偶爾也會不小心捕捉到宮廷裡本應悄然無聲的醜聞。","coverImage":null,"freeLayout":false,"manualPositions":{},"locked":false,"gameImport":true,"gameData":{"householdId":"944092612642842853","source":"game","homeZoneId":"944092612642842367","worldId":"1987342340","neighborhoodId":"944092612642770511","regionId":"487001","lotName":"阿布蘭特斯莊園","worldName":null,"neighborhoodName":"昂達里昂","hidden":false,"isActiveHousehold":false,"isPlayedHousehold":false,"isPlayerHousehold":false,"householdMemberIds":["944092612642842854","944092612642842855"],"petIds":[]}}
